import {infrastructure, mountInfrastructure} from './infrastructure.js';
import {industries as industriesTab} from './industries.js';
import {content, sources, rawWorkUrl, simulation} from './content.js';
const main = document.querySelector('main');
const escape = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = s => {try {const u=new URL(s,location.href); return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}};
const pending = '<span class="status"><i></i> RESEARCH IN PROGRESS</span>';
const section = (id,number,title,body,cls='') => `<section id="${id}" class="section ${cls}"><div class="section-label"><span>${number}</span><span>${title}</span></div>${body}</section>`;
const placeholder = (title,text) => `<div class="placeholder">${pending}<h3>${title}</h3><p>${text}</p></div>`;
// Use citation('source-id') in research copy once its matching bibliography record exists.
export const citation = id => sources.some(s=>s.id===id)?`<a class="citation" href="#research/source-${encodeURIComponent(id)}">[${escape(id)}]</a>`:'';
function economy(){return section('brief','01 / THE QUESTION','Our thesis',`<div class="brief-grid"><h2>FREE TO LAUNCH.<br>WHAT’S WORTH<br>MAKING?</h2><div><p class="large">Tomorrow, launching mass to orbit becomes effectively free. What is the first product that will be fundamentally cheaper to make in microgravity, and at what launch, manufacturing and return costs is it viable?</p><p>Cheap launch opens the door to many orbital industries, but one of the earliest real businesses may be growing stem cells in space. Transplant-grade stem cells are expensive to make on Earth. If microgravity lets you grow more usable cells per batch, the savings per dose could cover the cost of sending the hardware up and bringing the product back down.</p><p>Whether it works as a business comes down to one question: can cells grown in space beat what a terrestrial bioreactor produces at clinical grade?</p></div></div>`)+
section('medicine','02 / SPACE MEDICINE','Why this industry',`<div class="split"><div><h2>SMALL CELLS.<br>BIG QUESTIONS.</h2><p>Space medicine ranks first in our industry matrix. A biologic drug is worth about $47M per kilogram against roughly $7,000 per kilogram to launch, so launch was never the constraint. What gates it is biology, regulation and the trip home.</p><a class="button" href="#medicine/simulation">EXPLORE THE SIMULATION <span>↓</span></a></div><div class="research-list"><details><summary><span>01</span>Why medicine comes first<b>+</b></summary><p>Launch cost is becoming less of a barrier to space commercialization, but keeping people healthy for months or years in orbit is still a hard limit. If we cannot treat disease, manage the body’s decline in microgravity, or predict how drugs behave there, we cannot keep a permanent workforce in space.</p><p>Today the people who go up are astronauts with years of training. If the goal is to send large numbers of people, medicine is a must. Cities are not built without hospitals, and the same holds before space logistics or any other orbital industry.</p></details><details><summary><span>02</span>Why stem cells<b>+</b></summary><p>Labs grow stem cells and then prompt them, with chemicals and growth media, to multiply and turn into the specialized cells a transplant needs, such as heart or kidney cells. On Earth a large share of each batch differentiates early or into the wrong type: gravity flattens the cells against a 2D dish, and that mechanical stress triggers unintended tissue types.</p><p>In microgravity the cells float in 3D suspension with no scaffold. That suppresses the premature differentiation pathways, so a batch stays uniform and pluripotent until the targeted protocol is applied. Because the inputs are expensive, a higher share of correct cells directly lowers the cost per usable output.</p></details><details><summary><span>03</span>What has actually been measured<b>+</b></summary><p>Merck grew uniform drug crystals on the ISS <a class="citation" href="https://pubmed.ncbi.nlm.nih.gov/31815178/" target="_blank" rel="noreferrer">[PubMed]</a>. Cardiac progenitor cells grew about 20× more cells in orbit <a class="citation" href="https://www.cell.com/stem-cell-reports/fulltext/S2213-6711(22)00416-7" target="_blank" rel="noreferrer">[Stem Cell Reports]</a>. Lab systems that imitate microgravity have produced 1.5 to 4 times more working heart cells per starting stem cell than the best 3D culture on Earth.</p><p>Two things we keep in view: we found no published data showing lower cost per output, so the cost advantage is our hypothesis, and ground bioreactors that simulate microgravity already exist <a class="citation" href="https://spinoff.nasa.gov/Cosmic_Experiments_Make_Cosmetic_Nutrients" target="_blank" rel="noreferrer">[NASA Spinoff]</a>, which is a competing explanation for the same gains.</p></details></div></div>`)+
section('simulation','03 / INTERACTIVE LAB','Drug levels in orbit',`<div class="section-heading"><h2>SAME DOSE.<br>DIFFERENT BODY.</h2><p>ORBITALRx runs a standard pharmacokinetic model for an oral dose on Earth and in space. Toggle the condition, play the 24 hours, and change how strongly spaceflight alters the body.</p></div><div id="simulation-mount" class="simulation"></div>`)+
section('economics','04 / THE ECONOMICS','Stem-cell unit economics',`<div class="section-heading"><h2>CHEAPER TO GROW<br>IN ORBIT.</h2><p>The unit economics of stem-cell manufacturing: the launch, manufacturing and return costs at which space wins.</p></div><div class="calc-intro"><p class="large">What will be cheaper to make in space first? We think it&rsquo;s heart-muscle cells grown from stem cells.</p><p>Labs grow stem cells and then coax them into the specialized cells a patient needs, such as heart-muscle cells. On Earth, many batches lose cells to the wrong cell type, and every wasted cell carries the cost of expensive growth media, clean rooms and skilled staff. In microgravity, cells float freely in 3D. Lab experiments that imitate microgravity have produced 1.5 to 4 times more working heart cells per starting stem cell than the best 3D culture on Earth. Our calculator turns that into dollars per patient dose (about 150 million heart cells). On today&rsquo;s Space Station, space costs about 5 times more ($100,476 vs $19,552), mostly because of astronaut time, launch and the trip home. With three changes, space comes out cheaper at $14,854 per dose, 24% below Earth:</p><ul><li>cells grow about 3 times better</li><li>an automated factory satellite replaces astronauts</li><li>cheaper rockets and shared return capsules</li></ul><p>It stays cheaper as long as launch costs under about $7,200 per kg, the return trip costs under about $255,000 per batch, and microgravity delivers at least 2.3 times more cells. Across the full range of uncertainty, space wins in about half of modeled scenarios.</p></div><div class="calc-embed"><iframe id="calc-frame" title="Stem-cell cost calculator: Earth vs space" src="calculator/pitch.html?embed=1&amp;theme=dark&amp;skin=site"></iframe></div>`)+verdict();}
function verdict(){return section('verdict','05 / THE VERDICT','Where we land',`<div class="split"><div><h2>WHAT COMES<br>FIRST?</h2><p class="large">Transplant-grade cells grown in orbit, starting with heart-muscle cells from stem cells.</p></div><div><p>Space medicine is the strongest candidate in our matrix, but free launch is not what unlocks it; it already works at today’s prices. On our numbers space comes out at $14,854 per dose against $19,552 on Earth once cells grow about 3× better, an automated satellite replaces astronaut time, and launch falls under about $7,200 per kilogram with return under about $255,000 per batch.</p><p>Three things still gate it. Regulation: only the UK has a pathway <a class="citation" href="https://www.gov.uk/government/news/uk-sets-out-world-leading-pathway-for-space-manufactured-drugs" target="_blank" rel="noreferrer">[GOV.UK]</a> and the FDA has issued no guidance. Return: only Dragon and Varda routinely bring hardware back <a class="citation" href="https://mikekaplan978.substack.com/p/the-downmass-market" target="_blank" rel="noreferrer">[Downmass Market]</a>. Proof: no orbit-made medicine is approved anywhere <a class="citation" href="https://vegastrategy.substack.com/p/who-regulates-a-drug-made-in-orbit" target="_blank" rel="noreferrer">[Vega Strategy]</a>.</p><p>The cost advantage itself is still a hypothesis. No published study shows a lower cost per output from orbit, and ground bioreactors that simulate microgravity are the competing explanation. The first thing to prove is a clinical-grade batch from space that beats the best terrestrial bioreactor.</p><a class="text-link" href="#orbital-economy">NEXT: ORBITAL ECONOMY <span>↗</span></a></div></div>`);}
function research(){return `<section class="research-document" aria-label="Research document"><iframe title="Orbital Economy research Google Doc" src="${escape(safeUrl(rawWorkUrl.replace(/\/edit.*$/, '/preview')))}"></iframe></section>`;}
let current='', cleanup=null, renderGeneration=0;
// Size the embedded calculator (same-origin, dist/calculator/) to its content so it never shows an inner scrollbar.
function fitFrame(frame){const fit=()=>{try{const d=frame.contentDocument;if(d&&d.body)frame.style.height=Math.ceil(d.body.getBoundingClientRect().height)+'px';}catch{}};const later=()=>setTimeout(fit,60);const wire=()=>{fit();try{const w=frame.contentWindow,d=frame.contentDocument;new w.ResizeObserver(fit).observe(d.body);['click','input','keydown','toggle'].forEach(e=>d.addEventListener(e,later,true));w.addEventListener('resize',later);}catch{}};frame.addEventListener('load',wire);if(frame.contentDocument?.readyState==='complete'&&frame.contentDocument.body?.childElementCount)wire();}
function mountCalculator(){const frame=document.querySelector('#calc-frame');if(frame)fitFrame(frame);}
async function mountSimulation(generation){const el=document.querySelector('#simulation-mount');if(!el)return;try{if(simulation.iframeUrl&&safeUrl(simulation.iframeUrl)){el.replaceChildren();const frame=document.createElement('iframe');frame.title=simulation.title;frame.src=safeUrl(simulation.iframeUrl);frame.sandbox='allow-scripts allow-same-origin';frame.loading='lazy';el.append(frame);fitFrame(frame);}else if(simulation.moduleUrl){const module=await import(simulation.moduleUrl);if(generation!==renderGeneration)return;el.replaceChildren();const result=await module.mount(el);if(generation!==renderGeneration){if(typeof result==='function')result();return;}cleanup=typeof result==='function'?result:null;}}catch(e){if(generation===renderGeneration)el.innerHTML=placeholder('Simulation unavailable.','The simulation could not load. Please try reloading the page.');console.error(e);}}
const LEGACY={economy:'medicine',infrastructure:'orbital-economy'};
function route(){let [tab='industries',id]=location.hash.slice(1).split('/');if(LEGACY[tab]){location.replace('#'+LEGACY[tab]+(id?'/'+id:''));return;}if(!content[tab]){location.replace('#industries');return;}if(current!==tab){cleanup?.();cleanup=null;current=tab;const generation=++renderGeneration,c=content[tab];main.innerHTML=tab==='research'?research():`<div class="hero hero-${tab}" style="--hero:url('${c.image}')"><div class="hero-content"><span class="eyebrow">${c.eyebrow}</span><h1>${c.title.replaceAll('\n','<br>')}</h1><p>${c.description}</p><a class="button" href="#${tab}/${c.sections[0][0]}">${tab==='research'?'EXPLORE OUR WORK':'EXPLORE THE QUESTION'} <span>↓</span></a></div><div class="hero-bottom"><span>THE ORBITAL ECONOMY</span><a href="#${tab}/${c.sections[0][0]}" aria-label="Scroll to content">⌄</a><span>${tab==='research'?'RESEARCH & TEAM':`${c.number} / 03`}</span></div></div><nav class="section-nav" aria-label="Section navigation">${c.sections.map(([i,l])=>`<a href="#${tab}/${i}">${l}</a>`).join('')}</nav>${tab==='industries'?industriesTab():tab==='medicine'?economy():tab==='orbital-economy'?infrastructure():research()}`;document.title=`${c.label} — The Orbital Economy`;mountSimulation(generation);if(tab==='medicine')mountCalculator();if(tab==='orbital-economy')mountInfrastructure();}
document.querySelectorAll('[data-tab]').forEach(a=>{const active=a.dataset.tab===tab;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});document.querySelector('#navigation').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');requestAnimationFrame(()=>{const target=id?document.getElementById(id):null;if(target)target.scrollIntoView({behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'});});}
window.addEventListener('hashchange',route);document.querySelector('#menu-toggle').addEventListener('click',e=>{const open=document.querySelector('#navigation').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('#navigation').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');}});document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});document.querySelector('#print').addEventListener('click',()=>window.print());window.addEventListener('scroll',()=>document.querySelector('header').classList.toggle('scrolled',scrollY>40),{passive:true});route();
